package com.tekwatt.admin.controller;
import com.tekwatt.admin.dto.PlatformModuleResponse;import com.tekwatt.admin.service.ModuleService;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/modules") public class ModuleController{private final ModuleService service;public ModuleController(ModuleService service){this.service=service;}@GetMapping List<PlatformModuleResponse>list(@RequestParam UUID tenantId){return service.list(tenantId);}@PostMapping("/{moduleId}/install")PlatformModuleResponse install(@RequestParam UUID tenantId,@PathVariable String moduleId){return service.install(tenantId,moduleId);}@DeleteMapping("/{moduleId}")@ResponseStatus(HttpStatus.NO_CONTENT)void uninstall(@RequestParam UUID tenantId,@PathVariable String moduleId){service.uninstall(tenantId,moduleId);}}
